const binaryData = $binary || {};
const body = $json.body || $json;
const items = [];
items.push({ json: { type: 'message', message: body.message || '', history: body.history || [], sessionId: body.sessionId } });
for (const key of Object.keys(binaryData)) {
  items.push({ json: { type: 'file', fileName: binaryData[key].fileName, mimeType: binaryData[key].mimeType }, binary: { data: binaryData[key] } });
}
return items;

const all = await $input.all();
const result = { message: "", history: [], sessionId: "", documents: [], images: [] };
for (const item of all) {
  if (item.json.type === 'message') { result.message = item.json.message; result.history = item.json.history; result.sessionId = item.json.sessionId; }
  else if (item.json.fileName) {
    if (item.json.base64) result.images.push({ name: item.json.fileName, mimeType: item.json.mimeType, base64: item.json.base64 });
    else {
      let content = typeof item.json.data === 'string' ? item.json.data : JSON.stringify(item.json.data);
      const existingDoc = result.documents.find(d => d.name === item.json.fileName);
      if (existingDoc) existingDoc.content += "\n" + content;
      else result.documents.push({ name: item.json.fileName, content: content });
    }
  }
}
return result;

