// Calcular periodo baseado na hora de Curitiba (UTC-3)
const now = new Date();
const curitibaHour = (now.getUTCHours() - 3 + 24) % 24;

let periodo = null;
let saudacao = '';

if (curitibaHour >= 7 && curitibaHour < 9) {
  periodo = 'manha';
  saudacao = 'Bom dia';
} else if (curitibaHour >= 11 && curitibaHour < 13) {
  periodo = 'almoco';
  saudacao = 'Boa tarde';
} else if (curitibaHour >= 15 && curitibaHour < 17) {
  periodo = 'tarde';
  saudacao = 'Boa tarde';
} else if (curitibaHour >= 20 && curitibaHour < 23) {
  periodo = 'noite';
  saudacao = 'Boa noite';
}

const cliente = $input.first().json;

return [{
  json: {
    ...cliente,
    periodo,
    saudacao,
    hora_curitiba: curitibaHour
  }
}];

