const items = $input.all();
const results = [];
for (const item of items) {
  const updated = new Date(item.json.updated_at);
  const agora = new Date();
  const horas = (agora - updated) / (1000 * 60 * 60);
  const followup_num = item.json.numero_followup || 0;
  results.push({
    json: {
      ...item.json,
      horas_sem_resposta: Math.round(horas),
      followup_atual: followup_num
    }
  });
}
return results;

